#include <cstddef>
#include <span>
#include <vector>

bool AppendSelected(std::vector<int>& values,
                    std::span<const std::size_t> indices,
                    std::size_t limit) {
  if (values.size() > limit ||
      indices.size() > limit - values.size()) return false;
  for (auto index : indices) {
    if (index >= values.size()) return false;
    values.push_back(values[index]);
  }
  return true;
}
